-- EcoGram social features: interactions, stories, follows, chat, notifications and media.
begin;
create table if not exists public.ecogram_likes(post_id uuid not null references public.ecogram_posts(id) on delete cascade,user_id uuid not null references public.ecogram_profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create index if not exists ecogram_likes_user_idx on public.ecogram_likes(user_id,created_at desc);
create table if not exists public.ecogram_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.ecogram_posts(id) on delete cascade,user_id uuid not null references public.ecogram_profiles(id) on delete cascade,body text not null,created_at timestamptz not null default now(),constraint ecogram_comment_body_length check(char_length(trim(body)) between 1 and 1000));
create index if not exists ecogram_comments_post_idx on public.ecogram_comments(post_id,created_at asc);
create table if not exists public.ecogram_stories(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.ecogram_profiles(id) on delete cascade,image_path text not null,caption text not null default '',created_at timestamptz not null default now(),expires_at timestamptz not null default(now()+interval '24 hours'),constraint ecogram_story_caption_length check(char_length(caption)<=240));
create index if not exists ecogram_stories_expiry_idx on public.ecogram_stories(expires_at desc);
create table if not exists public.ecogram_challenge_progress(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.ecogram_profiles(id) on delete cascade,challenge_key text not null,progress_count integer not null default 0 check(progress_count>=0),target_count integer not null default 1 check(target_count>0),joined_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz,unique(user_id,challenge_key),constraint ecogram_challenge_key_format check(challenge_key ~ '^[a-z0-9-]{2,80}$'));
create table if not exists public.ecogram_follows(follower_id uuid not null references public.ecogram_profiles(id) on delete cascade,followed_id uuid not null references public.ecogram_profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,followed_id),constraint ecogram_no_self_follow check(follower_id<>followed_id));
create index if not exists ecogram_follows_followed_idx on public.ecogram_follows(followed_id,created_at desc);
create table if not exists public.ecogram_conversations(id uuid primary key default gen_random_uuid(),user_a uuid not null references public.ecogram_profiles(id) on delete cascade,user_b uuid not null references public.ecogram_profiles(id) on delete cascade,created_at timestamptz not null default now(),constraint ecogram_conversation_pair check(user_a::text<user_b::text),unique(user_a,user_b));
create table if not exists public.ecogram_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.ecogram_conversations(id) on delete cascade,sender_id uuid not null references public.ecogram_profiles(id) on delete cascade,body text not null,created_at timestamptz not null default now(),constraint ecogram_message_body_length check(char_length(trim(body)) between 1 and 2000));
create index if not exists ecogram_messages_conversation_idx on public.ecogram_messages(conversation_id,created_at asc);
create table if not exists public.ecogram_notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.ecogram_profiles(id) on delete cascade,actor_id uuid not null references public.ecogram_profiles(id) on delete cascade,kind text not null check(kind in('like','comment','follow','message','challenge')),related_id uuid,body text not null default '',created_at timestamptz not null default now(),read_at timestamptz);
create index if not exists ecogram_notifications_user_idx on public.ecogram_notifications(user_id,created_at desc);
alter table public.ecogram_likes enable row level security;alter table public.ecogram_comments enable row level security;alter table public.ecogram_stories enable row level security;alter table public.ecogram_challenge_progress enable row level security;alter table public.ecogram_follows enable row level security;alter table public.ecogram_conversations enable row level security;alter table public.ecogram_messages enable row level security;alter table public.ecogram_notifications enable row level security;
drop policy if exists ecogram_likes_read on public.ecogram_likes;create policy ecogram_likes_read on public.ecogram_likes for select to anon,authenticated using(true);
drop policy if exists ecogram_likes_insert_own on public.ecogram_likes;create policy ecogram_likes_insert_own on public.ecogram_likes for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists ecogram_likes_delete_own on public.ecogram_likes;create policy ecogram_likes_delete_own on public.ecogram_likes for delete to authenticated using((select auth.uid())=user_id);
drop policy if exists ecogram_comments_read on public.ecogram_comments;create policy ecogram_comments_read on public.ecogram_comments for select to anon,authenticated using(true);
drop policy if exists ecogram_comments_insert_own on public.ecogram_comments;create policy ecogram_comments_insert_own on public.ecogram_comments for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists ecogram_comments_update_own on public.ecogram_comments;create policy ecogram_comments_update_own on public.ecogram_comments for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists ecogram_comments_delete_own on public.ecogram_comments;create policy ecogram_comments_delete_own on public.ecogram_comments for delete to authenticated using((select auth.uid())=user_id);
drop policy if exists ecogram_stories_read_active on public.ecogram_stories;create policy ecogram_stories_read_active on public.ecogram_stories for select to anon,authenticated using(expires_at>now());
drop policy if exists ecogram_stories_insert_own on public.ecogram_stories;create policy ecogram_stories_insert_own on public.ecogram_stories for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists ecogram_stories_delete_own on public.ecogram_stories;create policy ecogram_stories_delete_own on public.ecogram_stories for delete to authenticated using((select auth.uid())=user_id);
drop policy if exists ecogram_challenges_read on public.ecogram_challenge_progress;create policy ecogram_challenges_read on public.ecogram_challenge_progress for select to anon,authenticated using(true);
drop policy if exists ecogram_challenges_insert_own on public.ecogram_challenge_progress;create policy ecogram_challenges_insert_own on public.ecogram_challenge_progress for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists ecogram_challenges_update_own on public.ecogram_challenge_progress;create policy ecogram_challenges_update_own on public.ecogram_challenge_progress for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists ecogram_challenges_delete_own on public.ecogram_challenge_progress;create policy ecogram_challenges_delete_own on public.ecogram_challenge_progress for delete to authenticated using((select auth.uid())=user_id);
drop policy if exists ecogram_follows_read on public.ecogram_follows;create policy ecogram_follows_read on public.ecogram_follows for select to anon,authenticated using(true);
drop policy if exists ecogram_follows_insert_own on public.ecogram_follows;create policy ecogram_follows_insert_own on public.ecogram_follows for insert to authenticated with check((select auth.uid())=follower_id);
drop policy if exists ecogram_follows_delete_own on public.ecogram_follows;create policy ecogram_follows_delete_own on public.ecogram_follows for delete to authenticated using((select auth.uid())=follower_id);
drop policy if exists ecogram_conversations_read_members on public.ecogram_conversations;create policy ecogram_conversations_read_members on public.ecogram_conversations for select to authenticated using((select auth.uid()) in(user_a,user_b));
drop policy if exists ecogram_conversations_insert_members on public.ecogram_conversations;create policy ecogram_conversations_insert_members on public.ecogram_conversations for insert to authenticated with check((select auth.uid()) in(user_a,user_b));
drop policy if exists ecogram_messages_read_members on public.ecogram_messages;create policy ecogram_messages_read_members on public.ecogram_messages for select to authenticated using(exists(select 1 from public.ecogram_conversations c where c.id=conversation_id and (select auth.uid()) in(c.user_a,c.user_b)));
drop policy if exists ecogram_messages_insert_members on public.ecogram_messages;create policy ecogram_messages_insert_members on public.ecogram_messages for insert to authenticated with check(sender_id=(select auth.uid()) and exists(select 1 from public.ecogram_conversations c where c.id=conversation_id and (select auth.uid()) in(c.user_a,c.user_b)));
drop policy if exists ecogram_messages_delete_own on public.ecogram_messages;create policy ecogram_messages_delete_own on public.ecogram_messages for delete to authenticated using(sender_id=(select auth.uid()));
drop policy if exists ecogram_notifications_read_own on public.ecogram_notifications;create policy ecogram_notifications_read_own on public.ecogram_notifications for select to authenticated using((select auth.uid())=user_id);
drop policy if exists ecogram_notifications_insert_actor on public.ecogram_notifications;create policy ecogram_notifications_insert_actor on public.ecogram_notifications for insert to authenticated with check((select auth.uid())=actor_id and user_id<>actor_id);
drop policy if exists ecogram_notifications_update_own on public.ecogram_notifications;create policy ecogram_notifications_update_own on public.ecogram_notifications for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists ecogram_notifications_delete_own on public.ecogram_notifications;create policy ecogram_notifications_delete_own on public.ecogram_notifications for delete to authenticated using((select auth.uid())=user_id);
grant select on public.ecogram_likes,public.ecogram_comments,public.ecogram_stories,public.ecogram_challenge_progress,public.ecogram_follows to anon;
grant select,insert,delete on public.ecogram_likes,public.ecogram_stories,public.ecogram_follows to authenticated;
grant select,insert,update,delete on public.ecogram_comments,public.ecogram_challenge_progress,public.ecogram_notifications to authenticated;
grant select,insert on public.ecogram_conversations to authenticated;
grant select,insert,delete on public.ecogram_messages to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('ecogram-media','ecogram-media',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists ecogram_media_upload_own on storage.objects;create policy ecogram_media_upload_own on storage.objects for insert to authenticated with check(bucket_id='ecogram-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists ecogram_media_update_own on storage.objects;create policy ecogram_media_update_own on storage.objects for update to authenticated using(bucket_id='ecogram-media' and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id='ecogram-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists ecogram_media_delete_own on storage.objects;create policy ecogram_media_delete_own on storage.objects for delete to authenticated using(bucket_id='ecogram-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
commit;
